615	/** Status carries meaning, so each one maps to a semantic badge variant. */
616	const STATUS_VARIANT: Readonly<Record<HeroStatus, BadgeVariant>> = {
617	  Active: 'success',
618	  Injured: 'warning',
619	  Reserve: 'secondary',
620	  MIA: 'destructive',
