670	  readonly found = computed(() => this.hero() !== undefined);
671	  readonly initials = computed(() => initialsOf(this.hero()?.name ?? ''));
672	  readonly statusVariant = computed(() => STATUS_VARIANT[this.hero()?.status ?? 'Reserve']);
673	  readonly deployable = computed(() => this.hero()?.status === 'Active');
674	
675	  readonly activeTab = signal<HeroDetailTab>('overview');
676	
677	  readonly stats = computed<readonly DetailStat[]>(() => {
678	    const hero = this.hero();
679	    if (!hero) return [];
680	    return [
681	      { label: 'Power index', value: String(hero.powerIndex), detail: 'Scale 0 to 100', icon: 'lucideZap' },
682	      { label: 'Clearance', value: `Tier ${hero.clearanceTier}`, detail: 'Access level', icon: 'lucideShieldAlert' },
683	      {
684	        label: 'Missions',
685	        value: String(hero.missionCount),
686	        detail: `${hero.successRate}% success`,
687	        icon: 'lucideActivity',
688	      },
689	    ];
690	  });
691	
692	  readonly dossier = computed<readonly DetailFact[]>(() => {
693	    const hero = this.hero();
694	    if (!hero) return [];
695	    return [
696	      { label: 'Hero ID', value: hero.id },
697	      { label: 'Power class', value: hero.powerClass },
698	      { label: 'Status', value: hero.status },
699	      { label: 'Clearance', value: `Tier ${hero.clearanceTier}` },
700	      { label: 'Notes', value: hero.notes || 'No notes on file.' },
701	    ];
702	  });
703	
704	  /** The mission record. Result badges follow the success rate: 75 and up good, 50 and up cautionary. */
705	  readonly missionResult = computed<{ label: string; variant: BadgeVariant }>(() => {
706	    const rate = this.hero()?.successRate ?? 0;
707	    if (rate >= 75) return { label: 'Reliable', variant: 'success' };
708	    if (rate >= 50) return { label: 'Mixed', variant: 'warning' };
709	    return { label: 'At risk', variant: 'destructive' };
