732	  save(): Promise<boolean> {
733	    return submit(this.form, async () => {
734	      const hero = this.hero();
735	      if (!hero) return;
736	      const values = heroEditSchema.parse(this.model());
737	      this.heroes.update(hero.id, {
738	        name: values.name,
739	        alias: values.alias,
740	        powerClass: values.powerClass,
741	        powerIndex: values.powerIndex,
742	        notes: values.notes,
