770	import { z } from 'zod';
771	import { POWER_CLASSES } from '../domain/hero.model';
772	import type { FormFieldMeta } from '../forms/form-field-meta';
773	
774	/**
775	 * The hero edit form. This schema is the single source of truth for the form's shape,
776	 * its rules, and its field labels. Labels ride on each field via `.meta()`.
777	 */
778	export const heroEditSchema = z.object({
779	  name: z.string().trim().min(1).meta({ label: 'Name', control: 'text' } satisfies FormFieldMeta),
780	  alias: z.string().trim().min(1).meta({ label: 'Alias', control: 'text' } satisfies FormFieldMeta),
781	  powerClass: z.enum(POWER_CLASSES).meta({
782	    label: 'Power class',
783	    control: 'select',
784	    options: POWER_CLASSES.map((value) => ({ value, label: value })),
785	  } satisfies FormFieldMeta),
786	  powerIndex: z.number().int().min(0).max(100).meta({
787	    label: 'Power index',
788	    control: 'number',
789	    help: 'Whole number from 0 to 100.',
790	  } satisfies FormFieldMeta),
791	  notes: z.string().trim().meta({ label: 'Notes', control: 'textarea' } satisfies FormFieldMeta),
792	  active: z.boolean().meta({ label: 'Active', control: 'checkbox' } satisfies FormFieldMeta),
793	});
794	
795	export type HeroModel = z.infer<typeof heroEditSchema>;
