@layer theme, base, components, utilities;
@import 'tailwindcss/theme.css' layer(theme);
@import 'tailwindcss/preflight.css' layer(base);
@import 'tailwindcss/utilities.css';

@import '@spartan-ng/brain/hlm-tailwind-preset.css';
/* You can add global styles to this file, and also import other style files */

/* Utilities for the Hero Ops tokens the spartan preset does not already map. */
@theme inline {
  --color-sidebar-muted: var(--sidebar-muted);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
}

/*
 * Hero Ops Console palette (prototype/capstone-build-spec.md, "Theme palette").
 * Each role is mapped onto spartan's own token. Where the spec's value fails
 * WCAG AA (checked by `npm run check:contrast`) the nearest passing value is
 * used and noted beside it.
 */
:root {
  color-scheme: light;

  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.625rem;

  /* page + text */
  --background: #f6f7fa;
  --foreground: #1b1e2b;

  /* card / popover */
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;

  /* action / primary. on-primary is #241a05, not the spec's #ffffff: white on
     #d8891a measures 2.80:1, dark ink on the same amber measures 6.13:1. */
  --primary: #d8891a;
  --primary-foreground: #241a05;

  /* muted surface; accent is the subtle hover background (spec gives no
     separate value, so it shares the muted surface) */
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;

  /* destructive-foreground is black, not the ink colour: #1b1e2b measures
     4.23:1 on this red, #000000 measures 5.37:1. */
  --destructive: #e5484d;
  --destructive-foreground: #000000;

  /* border / input */
  --border: #e4e7ef;
  --input: #e4e7ef;

  /* focus ring. The spec's amber @ 35% sits near 2.6:1 on the page, below the
     3:1 non-text floor, so a solid darker amber is used instead. */
  --ring: #b06a0c;

  /* navigation rail: dark in both themes */
  --sidebar: #1e2233;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #d8891a;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #2a2f45;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #2a2f45;
  --sidebar-ring: #d8891a;
  --sidebar-muted: #9aa0b4;

  /* semantic status colours, separate from the accent */
  --success: #2fb574;
  --warning: #e4802b;
  --info: #4f7cf0;
}

:root.dark {
  color-scheme: dark;

  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);

  --background: #0e1018;
  --foreground: #eceef6;

  --card: #171a26;
  --card-foreground: #eceef6;
  --popover: #171a26;
  --popover-foreground: #eceef6;

  --primary: #f5b843;
  --primary-foreground: #241a05;

  --secondary: #1e2231;
  --secondary-foreground: #eceef6;
  --muted: #1e2231;
  --muted-foreground: #9aa0b4;
  --accent: #1e2231;
  --accent-foreground: #eceef6;

  --destructive: #f2585d;
  --destructive-foreground: #1b1e2b;

  --border: #272b3b;
  --input: #272b3b;

  --ring: #f5b843;

  --sidebar: #10121c;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #f5b843;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #20263c;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #20263c;
  --sidebar-ring: #f5b843;
  --sidebar-muted: #8b90a6;

  --success: #3ecb84;
  --warning: #f0983f;
  --info: #6f97f6;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

