      heroes.map((hero) => (hero.id === id ? { ...hero, ...changes } : hero)),
    );
  }

  /** Retire one hero: remove them from the roster. Unknown ids are a no-op. */
  retire(id: string): void {
    this.roster.update((heroes) => heroes.filter((hero) => hero.id !== id));
  }
}

