function isPowerClass(value: unknown): value is PowerClass {
  return (POWER_CLASSES as readonly unknown[]).includes(value);
}

function initialsOf(name: string): string {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part.charAt(0))
    .join('')
    .toUpperCase();
}

