// Throwaway end-to-end flow check for the integrated console. Not part of the repo.
import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { join, extname } from 'node:path';
import { chromium } from 'file:///D:/Repos/angular-jig/node_modules/playwright/index.mjs';

const DIST = 'D:/Repos/angular-jig/dist/angular-jig/browser';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.svg': 'image/svg+xml', '.ico': 'image/x-icon' };

const server = createServer(async (req, res) => {
  const path = (req.url ?? '/').split('?')[0];
  let file = join(DIST, decodeURIComponent(path));
  try {
    if (!(await stat(file)).isFile()) throw new Error('not a file');
  } catch {
    file = join(DIST, 'index.html');
  }
  res.writeHead(200, { 'content-type': MIME[extname(file)] ?? 'application/octet-stream' });
  res.end(await readFile(file));
});
await new Promise((r) => server.listen(4311, '127.0.0.1', r));

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const base = 'http://127.0.0.1:4311';
const results = [];
const check = (name, ok, detail = '') => { results.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  -- ' + detail : ''}`); };
const settle = () => page.waitForTimeout(400);

try {
  // 1. Roster starts with 12 heroes.
  await page.goto(base + '/roster');
  await page.waitForSelector('table tbody tr');
  const rosterStart = await page.locator('table tbody tr').count();
  check('roster starts with 12 rows', rosterStart === 12, `rows=${rosterStart}`);

  // 2. Edit Silverwing's name on the dossier; expect it on the roster and dashboard.
  await page.goto(base + '/detail/HRO-0007');
  await page.getByRole('tab', { name: 'Edit' }).click();
  await settle();
  await page.locator('#hero-name').fill('Silverwing Prime');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await settle();
  await page.goto(base + '/roster');
  await page.waitForSelector('table tbody tr');
  const rosterText = await page.locator('table').innerText();
  check('edit on detail reaches roster', rosterText.includes('Silverwing Prime'));
  await page.goto(base + '/dashboard');
  await page.waitForSelector('.dashboard__table');
  const dashText = await page.locator('.dashboard__table').innerText();
  check('edit on detail reaches dashboard table', dashText.includes('Silverwing Prime'));
  await page.getByRole('button', { name: 'Open dossier for Silverwing Prime' }).waitFor().catch(() => {});

  // 3. Deploy an Active hero not in the field; missions live goes 5 -> 6 on dashboard.
  await page.goto(base + '/dashboard');
  await page.waitForSelector('app-stat-tile');
  const liveBefore = await page.locator('app-stat-tile').nth(1).innerText();
  await page.goto(base + '/detail/HRO-0063');
  await page.getByRole('button', { name: 'Deploy', exact: true }).click();
  await settle();
  await page.goto(base + '/missions');
  await page.waitForSelector('.missions__table');
  const liveRows = await page.locator('.missions__table').first().locator('tbody tr').count();
  check('deploy adds a live mission', liveRows === 6, `live rows=${liveRows}`);
  await page.goto(base + '/dashboard');
  await page.waitForSelector('app-stat-tile');
  const liveAfter = await page.locator('app-stat-tile').nth(1).innerText();
  check('dashboard missions-live tile moves', liveBefore.includes('5') && liveAfter.includes('6'), `before="${liveBefore.replace(/\n/g, ' ')}" after="${liveAfter.replace(/\n/g, ' ')}"`);

  // 4. Stand down that mission from the missions screen.
  await page.goto(base + '/missions');
  await page.waitForSelector('.missions__table');
  await page.getByRole('button', { name: 'Stand down Open deployment' }).click();
  await settle();
  const liveAfterStand = await page.locator('.missions__table').first().locator('tbody tr').count();
  check('stand down removes the mission', liveAfterStand === 5, `live rows=${liveAfterStand}`);

  // 5. Recruit a hero; lands on their dossier; roster grows to 13.
  await page.goto(base + '/recruit');
  await page.locator('#recruit-name').fill('Test Recruit');
  await page.locator('#recruit-alias').fill('Flow Check');
  await page.getByRole('button', { name: 'Recruit hero', exact: true }).click();
  await settle();
  const recruitUrl = page.url();
  check('recruit opens new dossier', /\/detail\/HRO-0082$/.test(recruitUrl), recruitUrl);
  await page.goto(base + '/roster');
  await page.waitForSelector('table tbody tr');
  const rosterAfterRecruit = await page.locator('table tbody tr').count();
  check('roster grows by one after recruit', rosterAfterRecruit === 13, `rows=${rosterAfterRecruit}`);

  // 6. Retire the recruit; roster back to 12.
  await page.goto(base + '/detail/HRO-0082');
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  await page.getByRole('button', { name: 'Retire hero', exact: true }).click();
  await settle();
  check('retire returns to roster', page.url().endsWith('/roster'), page.url());
  const rosterAfterRetire = await page.locator('table tbody tr').count();
  check('roster back to 12 after retire', rosterAfterRetire === 12, `rows=${rosterAfterRetire}`);

  // 7. Contain a threat; dashboard open-threat count drops 4 -> 3.
  await page.goto(base + '/threats');
  await page.waitForSelector('.threats__intro');
  await page.getByRole('button', { name: 'Contain Tidal surge sabotage' }).click();
  await settle();
  const threatIntro = await page.locator('.threats__intro').innerText();
  check('contain updates threat count', threatIntro.includes('3 open'), threatIntro.replace(/\n/g, ' '));
  await page.goto(base + '/dashboard');
  await page.waitForSelector('app-stat-tile');
  const threatTile = await page.locator('app-stat-tile').nth(3).innerText();
  check('dashboard open-threat tile follows', threatTile.includes('3'), threatTile.replace(/\n/g, ' '));

  // 8. Top-bar search lands on a filtered roster.
  await page.goto(base + '/dashboard');
  const search = page.getByRole('searchbox', { name: 'Search heroes' });
  await search.fill('Ada');
  await search.press('Enter');
  await settle();
  check('top-bar search navigates to roster with q', page.url().includes('/roster?q=Ada'), page.url());
  const searchRows = await page.locator('table tbody tr').count();
  check('search filters roster rows', searchRows === 1, `rows=${searchRows}`);

  // 9. Settings theme choice applies the dark class and persists.
  await page.goto(base + '/settings');
  await page.locator('#settings-theme').click();
  await page.getByRole('option', { name: 'Dark', exact: true }).click();
  await settle();
  const dark = await page.evaluate(() => document.documentElement.classList.contains('dark'));
  const stored = await page.evaluate(() => localStorage.getItem('hero-ops-theme'));
  check('settings dark choice applies and persists', dark && stored === 'dark', `dark=${dark} stored=${stored}`);
} catch (err) {
  results.push('ERROR ' + (err?.message ?? err).split('\n')[0]);
}

console.log(results.join('\n'));
console.log(errors.length ? 'console/page errors:\n  ' + errors.join('\n  ') : 'no console or page errors');
await browser.close();
server.close();

